/// A Type represents a type of Go.
/// All types implement the Type interface.
pub trait Type: std::fmt::Display + Any {
    fn __go_clone_box_type_(&self) -> Box<dyn Type + Send + Sync>;
    fn __go_as_any(&self) -> &dyn Any;
    fn __go_eq_type_(&self, other: &(dyn Type + Send + Sync)) -> bool;
    fn underlying(&mut self) -> Arc<Mutex<Option<Box<dyn Type + Send + Sync>>>>;
    fn string(&self) -> Arc<Mutex<Option<String>>>;
}

impl Clone for Box<dyn Type + Send + Sync> {
    fn clone(&self) -> Self {
        Type::__go_clone_box_type_(self.as_ref())
    }
}

impl GoValueClone for Box<dyn Type + Send + Sync> {
    fn go_value_clone(&self) -> Self {
        Type::__go_clone_box_type_(self.as_ref())
    }
}

impl GoComparable for Box<dyn Type + Send + Sync> {
    fn go_eq(&self, other: &Self) -> bool {
        self.__go_eq_type_(other.as_ref())
    }
    fn go_hash(&self, _seed: usize) -> usize {
        panic!("interface hash with uncomparable dynamic type")
    }
}

